<?php require '../includes/core.php';$u=require_user(true);$s=db()->query('SELECT p.*,u.name client FROM payments p JOIN users u ON u.id=p.user_id ORDER BY p.id DESC');layout_start('Pagamentos',$u);?><h1>Pagamentos de demonstração</h1><p class="notice-demo">Todos os registros abaixo são fictícios. Não houve cobrança real.</p><div class="card table-wrap"><table class="table"><tr><th>Cliente</th><th>Plano</th><th>Valor</th><th>Forma</th><th>Situação</th><th>Código</th></tr><?php foreach($s as $r):?><tr><td><?=h($r['client'])?></td><td><?=h($r['plan_name'])?></td><td><?=money($r['amount'])?></td><td><?=h($r['method'])?></td><td><span class="pill ok"><?=h($r['status'])?></span></td><td><?=h($r['transaction_code'])?></td></tr><?php endforeach;?></table></div><?php layout_end();?>